#!/usr/bin/env bash
set -Eeuo pipefail

script="$(cd "$(dirname "$0")" && pwd)/nat-gateway.sh"
tmp_dir="$(mktemp -d)"
trap 'rm -rf "$tmp_dir"' EXIT

export NAT_GW_ENV_FILE="$tmp_dir/nat-gateway.env"
# Load script functions without command dispatcher
eval "$(sed '/^opt=\$1$/,$d' "$script")"

# 1. Test to_nft_rate conversion
assert_rate() {
    local input=$1
    local want=$2
    local got
    got=$(to_nft_rate "$input")
    if [ "$got" != "$want" ]; then
        echo "FAIL to_nft_rate '$input': got '$got', want '$want'" >&2
        exit 1
    fi
}

assert_rate "500/s" "500/second"
assert_rate "500/sec" "500/second"
assert_rate "500/second" "500/second"
assert_rate "100/m" "100/minute"
assert_rate "100/min" "100/minute"
assert_rate "100/minute" "100/minute"
assert_rate "200/h" "200/hour"
assert_rate "200/hour" "200/hour"
assert_rate "50/d" "50/day"
assert_rate "50/day" "50/day"

if to_nft_rate "500/invalid" 2>/dev/null; then
    echo "FAIL to_nft_rate accepted invalid unit" >&2
    exit 1
fi

# 2. Test is_stateless_active with nftables
NFT_TABLE="ovn-vpc-nat-gw"
nft_cmd=stub_nft
iptables_save_cmd=""

# 2.1 Empty notrack chain
stub_nft() {
    cat <<'EOF'
table ip ovn-vpc-nat-gw {
	chain notrack {
		type filter hook prerouting priority -300; policy accept;
	}
}
EOF
}
if is_stateless_active ""; then
    echo "FAIL: empty nft notrack chain must not be treated as active stateless" >&2
    exit 1
fi

# 2.2 UDP-only notrack rule in nft
stub_nft() {
    cat <<'EOF'
table ip ovn-vpc-nat-gw {
	chain notrack {
		type filter hook prerouting priority -300; policy accept;
		ip protocol udp notrack
	}
}
EOF
}
if is_stateless_active ""; then
    echo "FAIL: udp-only nft notrack rule must not be treated as active stateless" >&2
    exit 1
fi

# 2.3 TCP notrack rule in nft
stub_nft() {
    cat <<'EOF'
table ip ovn-vpc-nat-gw {
	chain notrack {
		type filter hook prerouting priority -300; policy accept;
		ip protocol tcp notrack
	}
}
EOF
}
if ! is_stateless_active ""; then
    echo "FAIL: tcp nft notrack rule must be treated as active stateless" >&2
    exit 1
fi

# 2.4 Broad notrack rule in nft
stub_nft() {
    cat <<'EOF'
table ip ovn-vpc-nat-gw {
	chain notrack {
		type filter hook prerouting priority -300; policy accept;
		notrack
	}
}
EOF
}
if ! is_stateless_active ""; then
    echo "FAIL: broad nft notrack rule must be treated as active stateless" >&2
    exit 1
fi

# 3. Test is_stateless_active with iptables
nft_cmd=""
iptables_save_cmd=stub_iptables_save

# 3.1 UDP DNS NOTRACK only
stub_iptables_save() {
    cat <<'EOF'
# Generated by iptables-save
*raw
:PREROUTING ACCEPT [0:0]
-A PREROUTING -p udp -m udp --dport 53 -j NOTRACK
COMMIT
EOF
}
if is_stateless_active ""; then
    echo "FAIL: udp dns NOTRACK must not be treated as active stateless" >&2
    exit 1
fi

# 3.2 Tunnel UDP NOTRACK only
stub_iptables_save() {
    cat <<'EOF'
# Generated by iptables-save
*raw
:PREROUTING ACCEPT [0:0]
-A PREROUTING -p udp -m udp --dport 4789 -j CT --notrack
COMMIT
EOF
}
if is_stateless_active ""; then
    echo "FAIL: udp tunnel NOTRACK must not be treated as active stateless" >&2
    exit 1
fi

# 3.3 Broad NOTRACK without -p
stub_iptables_save() {
    cat <<'EOF'
# Generated by iptables-save
*raw
:PREROUTING ACCEPT [0:0]
-A PREROUTING -j NOTRACK
COMMIT
EOF
}
if ! is_stateless_active ""; then
    echo "FAIL: broad iptables NOTRACK must be treated as active stateless" >&2
    exit 1
fi

# 3.4 TCP NOTRACK
stub_iptables_save() {
    cat <<'EOF'
# Generated by iptables-save
*raw
:PREROUTING ACCEPT [0:0]
-A PREROUTING -p tcp -j NOTRACK
COMMIT
EOF
}
if ! is_stateless_active ""; then
    echo "FAIL: tcp iptables NOTRACK must be treated as active stateless" >&2
    exit 1
fi

echo "PASS: nat-gateway connlimit & stateless detection tests passed"
